Going Beyond - Twin Cities Map with leaflet

Below we show how to make the MN counties map in the leaflet package.

Codelibrary(leaflet)

mn_counties_leaf &lt;- mn_counties |&gt; st_transform(4326) # Leaflet expects this CRS for vectors
mn_cities_leaf &lt;- mn_cities |&gt; st_transform(4326)

cities_per_county &lt;- st_join(mn_cities_leaf, mn_counties_leaf) |&gt;
    st_drop_geometry() |&gt; # removes geometry - makes the following calculation more efficient
    count(name.x) 

cities_per_county = cities_per_county%&gt;%
  mutate(name=name.x)

mn_counties_leaf |&gt; 
    filter(name %in% c("Anoka", "Hennepin", "Ramsey", "Dakota", "Carver", "Washington", "Scott")) |&gt;
    left_join(cities_per_county) |&gt;
    leaflet() |&gt; 
    addProviderTiles("OpenStreetMap.Mapnik") |&gt; 
    addPolygons(
        color = "#444444", weight = 1, smoothFactor = 0.5, opacity = 1.0,
        fillOpacity = 0.5, fillColor = "yellow",
        highlightOptions = highlightOptions(color = "white", weight = 2, bringToFront = TRUE)) |&gt;
    addCircles(data = mn_cities_leaf |&gt; filter(county %in% paste(c("Anoka", "Hennepin", "Ramsey", "Dakota", "Carver", "Washington", "Scott"), "County")), color = "#444444")

The if-else if-else Control Structure
Often in functions, you will want to execute code chunks conditionally. In a programming language, control structures are parts of the language that allow you to control what code is executed. By far the most common is the if-else if-else structure.
if (logical_condition) {
    # some code
} else if (other_logical_condition) {
    # some code
} else {
    # some code
}

middle &lt;- function(x) {
    mean_x &lt;- mean(x, na.rm = TRUE)
    median_x &lt;- median(x, na.rm = TRUE)
    seems_skewed &lt;- (mean_x &gt; 1.5*median_x) | (mean_x &lt; (1/1.5)*median_x)
    if (seems_skewed) {
        median_x
    } else {
        mean_x
    }
}






To vectorize or not to vectorize



The if () else {} code is not vectorized; the logical condition in if() cannot be a logical vector of length longer than 1. If you want a vectorized version of conditional execution of code use if_else() or case_when(); these can be used in mutate().


✏️ Convert Temp
Write a function for converting temperatures that takes as input a numeric value and a unit (either “C” for Celsius or “F” for Fahrenheit). The function should convert the temperature from one unit to the other based on the following formulas:

To convert Celsius to Fahrenheit: (Celsius * 9/5) + 32

To convert Fahrenheit to Celsius: (Fahrenheit - 32) * 5/9



Codeconvert_temp &lt;- function(temp, unit) {
    if (unit=="F") {
        (temp - 32) * 5/9
    } else if (unit=="C") {
        (temp * 9/5) + 32
    }
}

convert_temp(0, unit = "C")

[1] 32

Codeconvert_temp(32, unit = "F")

[1] 0


✏️ Extract Domain Names
Write a function that extracts the domain name of a supplied email address. The function should return the domain name (e.g., “gmail.com”). If the input is not a valid email address, return “Invalid Email”. (A valid email ends in “dot something”.)

Codeextract_domain &lt;- function(email) {
    is_valid &lt;- str_detect(email, "@.+\\..+")
    if (is_valid) {
        str_extract(email, "@.+$") |&gt;
            str_remove("@")
    } else {
        "Invalid Email"
    }
}

extract_domain(email = "trd@mac.edu")

[1] "mac.edu"

Codeextract_domain(email = "trd@mac.")

[1] "Invalid Email"

Codeextract_domain(email = "trd@mac.net")

[1] "mac.net"

✏️ Keep Even Values
Return only even values (and no missing values).

Codeeven_values = function(vec){
  new_vec = vec
  for (i in vec){
    if (i %% 2 != 0){ 
      new_vec = new_vec[new_vec != i]}
  }
  print(new_vec)
}

even_values(c(1,2,3,4,5,6,7,8,9))

[1] 2 4 6 8

✏️ Remove Outliers
Write a function called remove_outliers that removes outliers in a dataset. The user should be able to supply the dataset (data), the variable to remove outliers in (what_var), and a threshold on the number of SDs away from the mean used to define outliers (sd_thresh). Write your function so that it runs as follows: remove_outliers(diamonds, what_var = carat, sd_thresh = 3).

Coderemove_outliers &lt;- function(data, what_var, sd_thresh) {
    data |&gt;
        mutate(zscore = ({{ what_var }} - mean({{ what_var }}, na.rm = TRUE))/sd({{ what_var }}, na.rm = TRUE)) |&gt;
        filter(zscore &lt;= sd_thresh)
}

✏️ Fit Model
Write a function called fit_model that implements the different settings for our diamonds analysis.

Codefit_model &lt;- function(data, mod_formula, remove_outliers) {
    if (remove_outliers) {
        data_clean &lt;- remove_outliers(data, what_var = carat, sd_thresh = 3)
    } else {
        data_clean &lt;- data
    }

    lm(mod_formula, data = data_clean)
}

✏️ Fit Model Variations
Last class we worked on an extended exercise where our goal was to write a series of functions and a for loop to repeat linear model fitting under different “settings” (removal of outliers, model formula choice).
Repeat this exercise using pmap().

You’ll need to use the df_arg_combos object, your remove_outliers() function, and your fit_model() function.
Review the solutions below for the necessary parts and make sure you understand each part.
Then, try to put it all together using pmap().


Codexs &lt;- diamonds |&gt; select(carat, cut, clarity, color) |&gt; names()


df_arg_combos &lt;- crossing(
    mod_formula = str_c("price ~ ", map_chr(seq_along(xs), ~ str_c(xs[1:.x], collapse = " + ")) ),
    remove_outliers = c(TRUE, FALSE)
)
